<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Models\Task;
use App\Models\FocusSession;
use App\Models\TimeEntry;
use App\Services\Identity;
use App\Services\TimeTrackingService;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class TimeTrackingTest extends TestCase {
 use RefreshDatabase;
 private function login(User $u): static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version])->withoutVite();}
 private function startData(array $extra=[]): array{return array_merge(['title'=>'Focused work','mode'=>'pomodoro','minutes'=>25,'billable'=>0],$extra);}
 private function entryData(array $extra=[]): array{return array_merge(['title'=>'Manual work','mode'=>'custom','billable'=>1,'started_at'=>'2026-11-27T09:00','ended_at'=>'2026-11-27T10:00'],$extra);}
 private function task(User $u): Task{$t=new Task(['title'=>'Study task','status'=>'pending','priority'=>'medium']);$t->workspace_id=Identity::personal($u)->id;$t->creator_id=$u->id;$t->save();return $t;}
 private function at(string $time): void{$this->travelTo(Carbon::parse($time,'UTC'));}
 private function change(FocusSession $s,string $action,int $version){return $this->post('/time/sessions/'.$s->id.'/transition',compact('action','version'));}
 public function test_guest_access_denied(): void{$this->get('/time')->assertRedirect('/login');$this->get('/time/report')->assertRedirect('/login');}
 public function test_timer_pause_resume_records_actual_segments(): void{$u=User::factory()->create();$this->at('2026-11-27 03:00:00');$this->login($u)->post('/time/start',$this->startData())->assertRedirect();$s=FocusSession::firstOrFail();$this->at('2026-11-27 03:10:00');$this->change($s,'pause',0)->assertRedirect();$this->assertSame('paused',$s->fresh()->state);$this->at('2026-11-27 03:20:00');$this->get('/time')->assertOk()->assertSee('00:10:00');$this->change($s,'resume',1)->assertRedirect();$this->at('2026-11-27 03:35:00');$this->change($s,'stop',2)->assertRedirect();$this->assertSame('completed',$s->fresh()->state);$this->assertNull($s->fresh()->active_workspace_id);$this->assertSame(1500,app(TimeTrackingService::class)->elapsed($s->fresh()));$this->assertSame(2,$s->entries()->count());}
 public function test_duplicate_start_and_stale_transition_rejected(): void{$u=User::factory()->create();$this->at('2026-11-27 03:00:00');$this->login($u)->post('/time/start',$this->startData())->assertRedirect();$s=FocusSession::firstOrFail();$this->post('/time/start',$this->startData())->assertSessionHasErrors('timer');$this->at('2026-11-27 03:01:00');$this->change($s,'pause',0)->assertRedirect();$this->change($s,'resume',0)->assertSessionHasErrors('timer');$this->assertSame(1,FocusSession::count());}
 public function test_manual_time_validates_overlap_future_and_duration(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->at('2026-11-27 08:00:00');$this->login($u)->post('/time/entries',$this->entryData())->assertRedirect();$this->assertSame('2026-11-27 03:00:00',TimeEntry::firstOrFail()->started_at->format('Y-m-d H:i:s'));$this->post('/time/entries',$this->entryData(['started_at'=>'2026-11-27T09:30']))->assertSessionHasErrors('started_at');$this->post('/time/entries',$this->entryData(['started_at'=>'2026-11-27T11:00']))->assertSessionHasErrors('ended_at');$this->post('/time/entries',$this->entryData(['ended_at'=>'2026-11-28T10:00']))->assertSessionHasErrors('ended_at');$this->post('/time/entries',$this->entryData(['started_at'=>'2026-11-27T10:00','ended_at'=>'2026-11-27T11:00']))->assertRedirect();$this->assertSame(2,TimeEntry::count());}
 public function test_running_timer_blocks_overlapping_manual_entry(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->at('2026-11-27 03:00:00');$this->login($u)->post('/time/start',$this->startData())->assertRedirect();$this->at('2026-11-27 05:00:00');$this->post('/time/entries',$this->entryData())->assertSessionHasErrors('started_at');}
 public function test_correction_and_removal_preserve_history(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->at('2026-11-27 08:00:00');$this->login($u)->post('/time/entries',$this->entryData())->assertRedirect();$e=TimeEntry::firstOrFail();$this->get('/time/entries/'.$e->id.'/edit')->assertOk();$this->put('/time/entries/'.$e->id,$this->entryData(['ended_at'=>'2026-11-27T10:30','reason'=>'Correct duration']))->assertRedirect();$this->assertSame(5400,$e->fresh()->seconds());$this->assertSame(1,$e->revisions()->count());$this->delete('/time/entries/'.$e->id,['reason'=>'Duplicate record'])->assertRedirect();$this->assertSoftDeleted($e);$this->assertSame(2,$e->revisions()->count());}
 public function test_foreign_task_and_timer_access_denied(): void{$u=User::factory()->create();$other=User::factory()->create();$t=$this->task($other);$this->at('2026-11-27 08:00:00');$this->login($other)->post('/time/start',$this->startData(['title'=>'Private focus']))->assertRedirect();$s=FocusSession::firstOrFail();$e=$s->entries()->firstOrFail();$this->login($u)->withSession(['workspace_id'=>Identity::personal($u)->id])->get('/time')->assertOk()->assertDontSee('Private focus');$this->change($s,'stop',0)->assertNotFound();$this->get('/time/entries/'.$e->id.'/edit')->assertNotFound();$this->post('/time/start',$this->startData(['task_id'=>$t->id]))->assertSessionHasErrors('task_id');}
 public function test_business_workspace_denied(): void{$u=User::factory()->create();$w=Workspace::create(['owner_id'=>$u->id,'name'=>'Business','type'=>'business']);$this->login($u)->withSession(['workspace_id'=>$w->id])->get('/time')->assertForbidden();}
 public function test_breaks_not_billable_and_reports_split_midnight(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->at('2026-11-28 08:00:00');$this->login($u)->post('/time/entries',$this->entryData(['started_at'=>'2026-11-27T23:30','ended_at'=>'2026-11-28T00:30']))->assertRedirect();$this->post('/time/entries',$this->entryData(['mode'=>'short_break']))->assertSessionHasErrors('mode');$this->post('/time/entries',$this->entryData(['mode'=>'short_break','billable'=>0,'started_at'=>'2026-11-28T01:00','ended_at'=>'2026-11-28T01:15']))->assertRedirect();$w=Identity::personal($u);$r=app(TimeTrackingService::class)->report($w,Carbon::parse('2026-11-27','Asia/Dhaka'),Carbon::parse('2026-11-29','Asia/Dhaka'));$this->assertSame(3600,$r['totals']['work']);$this->assertSame(3600,$r['totals']['billable']);$this->assertSame(900,$r['totals']['break']);$this->assertSame(1800,$r['days']['2026-11-27']['work']);$this->assertSame(1800,$r['days']['2026-11-28']['work']);$this->get('/time/report?date=2026-11-28&period=week')->assertOk()->assertSee('Billable hours');}
 public function test_dashboard_and_entry_views_render_privately(): void{$u=User::factory()->create();$this->login($u)->get('/dashboard')->assertOk()->assertSee('Focus &amp; time today',false);$this->get('/time/entries/create')->assertOk();$this->get('/time/entries')->assertOk()->assertHeader('Cache-Control','no-store, private');}
}
